23		char *beginptr;
24		char *endptr;
25		long address;
26	
27		if (strncmp("reboot", cmd, length) == 0) {
28			sys_reboot(SYS_REBOOT_COLD);
29		} else if (strncmp("status", cmd, length) == 0) {
30			printk("%d %d\n", instr_tracing_supported(), instr_profiling_supported());
31		} else if (strncmp("ping", cmd, length) == 0) {
32			printk("pong\n");
33		} else if (strncmp("dump_trace", cmd, length) == 0) {
34			instr_dump_buffer_uart();
35		} else if (strncmp("dump_profile", cmd, length) == 0) {
36			instr_dump_deltas_uart();
37		} else if (strncmp(cmd, "trigger", strlen("trigger")) == 0) {
38			beginptr = cmd + strlen("trigger");
39			address = strtol(beginptr, &endptr, 16);
40			if (endptr != beginptr) {
41				instr_set_trigger_func((void *)address);
42			} else {
43				printk("trigger: invalid argument in: '%s'\n", cmd);
44			}
45		} else if (strncmp(cmd, "stopper", strlen("stopper")) == 0) {
46			beginptr = cmd + strlen("stopper");
47			address = strtol(beginptr, &endptr, 16);
48			if (endptr != beginptr) {
49				instr_set_stop_func((void *)address);
50			} else {
51				printk("stopper: invalid argument in: '%s'\n", cmd);
52			}
53		} else if (strncmp("listsets", cmd, length) == 0) {
54			void *address;
55	
56			address = instr_get_trigger_func();
57			if (address) {
58				printk("trigger: %p\n", address);
59			} else {
60				printk("trigger: not set.\n");
61			}
62	
63			address = instr_get_stop_func();
64			if (address) {
65				printk("stopper: %p\n", address);
66			} else {
67				printk("stopper: not set.\n");
68			}
69		} else {
