75	static void uart_isr(const struct device *uart_dev, void *user_data)
76	{
77		uint8_t byte = 0;
78		static uint32_t cur;
79	
80		ARG_UNUSED(user_data);
81	
82		if (!uart_irq_update(uart_dev)) {
83			return;
84		}
85	
86		if (!uart_irq_rx_ready(uart_dev)) {
87			return;
88		}
89	
90		while (uart_fifo_read(uart_dev, &byte, 1) == 1) {
91			if (!isprint(byte)) {
92				if (byte == '\r') {
93					_cmd_buffer[cur] = '\0';
94					handle_cmd(_cmd_buffer, cur);
95					cur = 0U;
96				}
97	
98				continue;
99			}
100	
101			if (cur < (COMMAND_BUFFER_SIZE - 1)) {
102				_cmd_buffer[cur++] = byte;
103			}
104		}
105	}
