111	
112		__ASSERT(device_is_ready(uart_dev), "uart_dev is not ready");
113	
114		uart_irq_rx_disable(uart_dev);
115		uart_irq_tx_disable(uart_dev);
116	
117		/* Set RX irq. handler */
118		uart_irq_callback_user_data_set(uart_dev, uart_isr, NULL);
119	
120		/* Clean RX FIFO before enabling interrupt. */
121		while (uart_irq_rx_ready(uart_dev)) {
122			uint8_t c;
123	
124			uart_fifo_read(uart_dev, &c, 1);
125		}
126	
127		/* Enable RX interruption. */
