```c
static int gpio_bk7258_port_toggle_bits(const struct device *dev,
                                          gpio_port_pins_t mask)
{
    const struct gpio_bk7258_config *cfg = dev->config;
    uint32_t reg, reg_addr;
    for (gpio_pin_t i = 0; mask != 0U; i++) {
        if (!(mask & BIT(i))) continue;
        mask &= ~BIT(i);
        reg_addr = cfg->reg_base + i * 4;
        reg = sys_read32(reg_addr);
        reg ^= BK7258_GPIO_OUTPUT;    /* 翻转 bit1 */
        sys_write32(reg, reg_addr);
    }
    return 0;
}
```

