#### b. pin_interrupt_configure
```c
static int gpio_bk7258_pin_interrupt_configure(const struct device *dev,
                                               gpio_pin_t pin,
                                               gpio_int_mode_t mode,
                                               gpio_int_trig_t trig)
{
    /* 映射 Zephyr mode+trig → BK7258 int_type */
    /* DISABLED: 清 gpio_int_en */
    /* LEVEL: trig=LOW → LOW_LEVEL, trig=HIGH → HIGH_LEVEL */
    /* EDGE: trig=FALLING → FALLING_EDGE, trig=RISING → RISING_EDGE, BOTH → FALLING_EDGE */
    /* 写 gpio_int_type 位 + 使能/禁用 gpio_int_en */
}
```

#### c. manage_callback
```c
static int gpio_bk7258_manage_callback(const struct device *dev,
                                       struct gpio_callback *callback,
                                       bool set)
{
    /* 用 sys_slist_append / sys_slist_remove 管理 callbacks 列表 */
    return gpio_manage_callback(&data->callbacks, callback, set);
}
```

#### d. get_pending_int
```c
static uint32_t gpio_bk7258_get_pending_int(const struct device *dev)
{
    /* 读 gpio_0_31_int_status，返回已启用中断的 pending 掩码 */
}
```

#### e. IRQ handler
```c
static void gpio_bk7258_isr(const struct device *dev)
{
    uint32_t status = gpio_bk7258_get_pending_int(dev);
    gpio_fire_callbacks(&data->callbacks, dev, status);
}
```

#### f. init 函数
```c
static int gpio_bk7258_init(const struct device *dev)
{
    IRQ_CONNECT(DT_INST_IRQN(0), DT_INST_IRQ(0, priority),
                gpio_bk7258_isr, DEVICE_DT_GET(DT_DRV_INST(0)), 0);
    irq_enable(DT_INST_IRQN(0));
    return 0;
}
