### 3. main.c 回调测试

```c
#include <stdio.h>
#include <zephyr/kernel.h>
#include <zephyr/drivers/gpio.h>

#define LED_PIN    9
#define BUTTON_PIN 29

static struct gpio_callback button_cb;

static void button_pressed(const struct device *dev, struct gpio_callback *cb,
                           uint32_t pins)
{
    /* 按下时翻转 LED */
    static const struct device *led_dev = DEVICE_DT_GET(DT_NODELABEL(gpio0));
    gpio_pin_toggle(led_dev, LED_PIN);
}

int main(void)
{
    printf("Hello World! %s\n", CONFIG_BOARD_TARGET);

    const struct device *gpio_dev = DEVICE_DT_GET(DT_NODELABEL(gpio0));
    if (!device_is_ready(gpio_dev)) {
        printf("gpio not ready\n");
        return 0;
    }

    /* LED 输出 */
    gpio_pin_configure(gpio_dev, LED_PIN, GPIO_OUTPUT);
    gpio_pin_set(gpio_dev, LED_PIN, 1);

    /* 按键输入 + 中断 */
    gpio_pin_configure(gpio_dev, BUTTON_PIN, GPIO_INPUT);
    gpio_init_callback(&button_cb, button_pressed, BIT(BUTTON_PIN));
    gpio_add_callback(gpio_dev, &button_cb);
    gpio_pin_interrupt_configure(gpio_dev, BUTTON_PIN,
                                  GPIO_INT_MODE_EDGE, GPIO_INT_TRIG_FALLING);

    printf("GPIO interrupt test ready\n");

    while (1) {
        k_sleep(K_MSEC(1000));
    }
    return 0;
}
